# ⭐ 30/09 (sceau Maeva : « j'aime trop les chiffres dans le POW ») :
#    LES CHIFFRES SONT AUSSI GROS QUE SA PLANCHE LE PERMET, RANGÉE PAR
#    RANGÉE. Ses trois rangées ne font pas la même hauteur :
#        rangée du haut   10,4 mm  ->  35 pt
#        rangée du milieu 10,3 mm  ->  35 pt
#        rangée du bas     8,8 mm  ->  29 pt   (c'est celle du soleil)
#    MESURÉ sur les 128 cases d'une feuille : il reste 0,44 mm de blanc
#    avant son trait au plus serré. Mettre 35 pt aussi en bas ferait
#    toucher les chiffres. Pour avoir 38 pt partout comme le POW, il
#    faudrait que ses trois rangées fassent 11,5 mm chacune.
_T_RANGEES = [35.0, 35.0, 29.0]
_T_CASE = max(_T_RANGEES)
_T_SERIE = 10.5


def _graver_planche(c):
    """Grave la planche UNE FOIS par document. Renvoie son nom.
    La marque est posée SUR LE CANEVAS, jamais dans un dictionnaire indexé
    par id() : Python réutilise les id() libérés."""
    nom = "SUN_DECOR"
    if not getattr(c, "_sun_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._sun_forme_faite = True
    return nom


def _poser_decor(c, x0, y0, couleurs):
    """Tamponne la planche UNE FOIS PAR CARTON, chacun dans SA couleur."""
    nom = _graver_planche(c)
    marge = 0.3 * mm
    for gi, (bord, cadre, _cx, _ry, _se) in enumerate(CARTES):
        gx = x0 + bord[0] / 1000.0 * FEUILLE_W - marge
        gl = (bord[1] - bord[0]) / 1000.0 * FEUILLE_W + 2 * marge
        gy = y0 + FEUILLE_H - cadre[1] / 1000.0 * FEUILLE_H - marge
        gh = (cadre[1] - cadre[0]) / 1000.0 * FEUILLE_H + 2 * marge
        c.saveState()
        fen = c.beginPath()
        fen.rect(gx, gy, gl, gh)
        c.clipPath(fen, stroke=0, fill=0)
        c.setFillColor(couleurs[gi])
        c.translate(x0, y0)
        c.doForm(nom)
        c.restoreState()


def _gen_grille(rng):
    """HUIT numéros, exactement les plages du SUN.
    col 1 : 1-8 (trois) · col 2 : 9-16 (deux) · col 3 : 17-24 (trois),
    triés du plus petit en haut au plus grand en bas.
    La case du BAS-MILIEU reste vide : c'est son soleil."""
    c1 = sorted(rng.sample(range(PLAGES[0][0], PLAGES[0][1] + 1), 3))
    c3 = sorted(rng.sample(range(PLAGES[2][0], PLAGES[2][1] + 1), 3))
    c2 = sorted(rng.sample(range(PLAGES[1][0], PLAGES[1][1] + 1), 2))
    milieu = []
    it = iter(c2)
    for r in range(LIGNES):
        milieu.append(None if r == CASE_VIDE else next(it))
    return [[c1[r], milieu[r], c3[r]] for r in range(LIGNES)]


# DEUX CARTONS IDENTIQUES DANS LA MÊME RAME : ce jeu ne peut fabriquer que
#    56 × 28 × 56 = 87 808 cartons différents. Une rame de 500 feuilles en
#    contient 8 000 : sans garde-fou, le calcul donne plus de 350 doublons
#    par rame. On garde donc en mémoire, pendant tout le document, les
#    cartons déjà sortis.
def _tirer(rng, deja):
    for _ in range(400):
        g = _gen_grille(rng)
        cle = tuple(tuple(r) for r in g)
        if cle not in deja:
            deja.add(cle)
            return g
    return g


def _dessiner_feuille(c, x0, y0, grilles, series, couleurs, titre_jeu="",
                      telephone="", style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    _poser_decor(c, x0, y0, couleurs)

    def MX(v):
        return x0 + v / 1000.0 * FEUILLE_W

    def MY(v):
        return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (bord, cadre, colx, rowy, serie) in enumerate(CARTES):
        grille = grilles[gi]
        for ri in range(LIGNES):
            # ⚠️ 0,36 et pas 0,329 : c'est ce qui centre vraiment le chiffre
            #    dans sa case, et c'est ce qui permet de le grossir.
            taille = _T_RANGEES[ri]
            cy = MY((rowy[ri] + rowy[ri + 1]) / 2.0) - taille * 0.36
            for ci in range(3):
                val = grille[ri][ci]
                if val is None:
                    continue
                cx = MX((colx[ci] + colx[ci + 1]) / 2.0)
                if _sec:
                    _sec.chiffre_micro(c, val, cx, cy, taille, gris_ch, police_ch,
                                       epaisseur=_GRAS_TRAIT)
                else:
                    c.setFillColor(gris_ch)
                    c.setFont(police_ch, taille)
                    c.drawCentredString(cx, cy, str(val))
        # le numéro de série reprend EXACTEMENT la place de son faux numéro
        c.setFillColor(GRIS)
        c.setFont(POLICE, _T_SERIE)
        c.drawRightString(MX(serie[0]), MY(serie[1]), "%06d" % series[gi])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(bord[0]), MY(cadre[1]),
                                 MX(bord[1]) - MX(bord[0]),
                                 MY(cadre[0]) - MY(cadre[1]),
                                 series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=16, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="",
                page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    rng = random.Random(240000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()

    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.6 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.6 * mm, "%03d" % no_page)

        grilles = [_tirer(rng, _deja) for _k in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        # UNE COULEUR PAR CARTON.
        couleurs = [colors.HexColor(
            couleur_perso if (couleur and couleur_perso)
            else RAINBOW[(s - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
            for s in series]
        _dessiner_feuille(c, MARGE_X, MARGE_Y, grilles, series, couleurs,
                          titre_jeu, telephone, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf




